<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$slug=trim($_GET['slug']??'');
$q=db()->prepare('SELECT * FROM categories WHERE slug=? AND is_active=1');$q->execute([$slug]);$category=$q->fetch();
if(!$category){http_response_code(404);exit('دسته‌بندی پیدا نشد.');}
$stmt=db()->prepare("SELECT p.*, (SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM products p JOIN product_categories pc ON pc.product_id=p.id WHERE pc.category_id=? AND p.status='published' ORDER BY p.is_featured DESC,p.id DESC");
$stmt->execute([$category['id']]);$products=$stmt->fetchAll();
$siteName=setting('site_name','Crivit Iran');$siteLogo=setting('site_logo','');
function renderCategoryProducts(array $items):void{?>
<div class="product-grid"><?php foreach($items as $p):?><article class="product-card"><a class="product-image" href="/product.php?slug=<?=rawurlencode($p['slug'])?>"><?php if($p['image_path']):?><img loading="lazy" src="<?=e($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="image-placeholder"><span>CRIVIT</span></div><?php endif?><?php if($p['sale_price']):?><span class="sale-badge">پیشنهاد ویژه</span><?php endif?></a><div class="product-info"><a class="product-name" href="/product.php?slug=<?=rawurlencode($p['slug'])?>"><?=e($p['name'])?></a><div class="product-bottom"><span class="stock-label <?=((int)$p['stock_quantity']>0?'available':'unavailable')?>"><?=((int)$p['stock_quantity']>0?'موجود':'ناموجود')?></span><div class="price"><strong><?=number_format((float)($p['sale_price']??$p['price']))?> <small>تومان</small></strong></div></div></div></article><?php endforeach?></div>
<?php } ?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($category['name'])?> | <?=e($siteName)?></title><link rel="stylesheet" href="/assets/style.css"></head><body class="storefront">
<div class="topline"><div class="topline-inner"><span>تجهیزات ورزشی و لوازم ماجراجویی</span><span>انتخاب حرفه‌ای، تجربه خرید مطمئن</span></div></div>
<header class="store-header"><a class="brand" href="/"><?php if($siteLogo):?><img class="brand-logo" src="<?=e($siteLogo)?>" alt="<?=e($siteName)?>"><?php else:?><span class="brand-mark">C</span><?php endif?><span><?=e($siteName)?><small>SPORT & OUTDOOR</small></span></a><form class="search" action="/" method="get"><button aria-label="جستجو">⌕</button><input name="q" placeholder="جستجوی محصولات..."></form><div class="header-actions"><a href="/admin/login.php"><span class="action-icon">♙</span><span>حساب کاربری</span></a></div></header>
<nav class="main-nav"><div class="nav-inner"><a class="nav-home" href="/">صفحه اصلی</a><a href="/#categories">دسته‌بندی‌ها</a><a href="/#products">همه محصولات</a></div></nav>
<main class="store-main"><div class="listing-heading"><span>دسته‌بندی محصولات</span><h1><?=e($category['name'])?></h1><?php if($category['description']):?><p><?=e($category['description'])?></p><?php endif?></div><?php if($products):renderCategoryProducts($products);else:?><div class="empty-state">در این دسته‌بندی هنوز محصولی منتشر نشده است.</div><?php endif?></main>
<footer class="store-footer"><div class="footer-brand"><strong><?=e($siteName)?></strong><p>همراه شما برای انتخاب تجهیزات ورزشی.</p></div><div><strong>دسترسی سریع</strong><a href="/">صفحه اصلی</a><a href="/#products">محصولات</a></div><div><strong>راهنمای خرید</strong><a href="/admin/login.php">حساب کاربری</a></div><div class="footer-copy">© تمامی حقوق محفوظ است.</div></footer></body></html>